INSERT INTO public.songs (id, title, artist, album, lyrics, url, poster_url, duration, stem_vocals, stem_drums, stem_bass, stem_other, needs_stems, created_at) VALUES (
  '862a7fa8-2236-42b0-bbd6-b8a280a49c69',
  'Akuma no Ko - English Version',
  'Ai Higuchi, Sati Akura',
  'Attack on Titan',
  '[00:00.17]These iron bullets,
[00:01.23]the sole proof of justice
[00:02.67]And if you get through,
[00:03.83]you will get closer to the hero
[00:05.47]Just close your eyes
[00:06.60]and reach out to touch it
[00:08.00]The evil that wraps all around you,
[00:10.57]taking that familiar shape
[00:13.30]Am I not worthy and is he just better?
[00:15.97]There′ s nothing I could
[00:17.27]do behind the highest wall
[00:18.67]No point in mourning the fate
[00:20.10]that we have chosen
[00:21.33]Because there is freedom
[00:23.23]awaiting us in the end
[00:25.17]Bestow upon me these
[00:27.80]shining silver wings
[00:30.47]So I could go somewhere
[00:33.57]I''ve never been
[00:35.83]And if there is no place
[00:38.40]for me to come back to
[00:41.30]Then I might never leave
[00:45.27]Is this the kind of life
[00:47.50]that I would want to live?
[00:50.80]This world is cruel, but I′m still in love
[00:56.17]With you and how you
[00:58.27]bring peace into my heart
[01:01.57]Even if I sacrifice it all
[01:06.93]I''ll fight for you,
[01:08.43]fight for you no matter what
[01:11.53]Even if it is one big mistake
[01:14.23]I won''t give it up, won′t back away
[01:16.67]Believing in myself each and every day
[01:19.37]It is exactly how it′s gonna stay
[01:31.97]I saw a scene where it was raining iron
[01:34.70]It didn''t look real,
[01:35.73]looked like a movie on TV
[01:37.33]This war′s as foolish as it is ferocious
[01:40.03]It doesn''t matter,
[01:41.03]the story of a distant country
[01:42.83]But I still hate it and it is the reason
[01:45.33]Why I can′ t seem to hide
[01:46.63]all of my black feelings
[01:47.87]And I can''t explain it, this contradiction
[01:50.73]I can′ t help but think how
[01:52.37]erratic we really are
[02:15.83]And even if this word''s
[02:18.20]translated for us now
[02:21.20]Its true meaning will never get across
[02:26.47]Make me believe that I,
[02:28.97]when opening my eyes
[02:31.53]Will be able to touch the world
[02:35.93]I just don''t want this
[02:37.83]senseless life to carry on
[02:44.13]This world is cruel, but I′m still in love
[02:49.47]With you and how you
[02:51.73]bring peace into my heart
[02:54.90]Even if I sacrifice it all
[03:00.20]I′ ll fight for you,
[03:01.80]fight for you no matter what
[03:04.67]The shadow of the person whom I chose
[03:07.47]The corpse of the abandoned one I lost
[03:10.03]I noticed that it was the devil''s little child
[03:12.67]That had been growing in me all this time
[03:15.30]The things I justified and all the sacrifice
[03:17.97]There is the devil′ s
[03:19.33]child inside my heart',
