INSERT INTO public.songs (id, title, artist, album, lyrics, url, poster_url, duration, stem_vocals, stem_drums, stem_bass, stem_other, needs_stems, created_at) VALUES (
  '2fa75852-1544-407c-a771-b9a2f7688e00',
  ' Get Him Back!',
  'Olivia Rodrigo',
  'GUTS',
  '[00:00.01] One, two, three
[00:03.29] Wait, is this the song with the drums?
[00:05.51] I met a guy in the summer and I left him in the spring
