[01:39.54]फिकर भी है पर दिखाती नहीं, प्यार भी होके जताती नहीं
[01:44.28]ख्वाबों से मेरे तू जाती नहीं, क्यों ये बता
[01:48.13]
[01:48.61]हूं मुसाफ़िर सा ढूंढू मैं अपना बसेरा
